// ============================================================
// RÉCONCILIATION : Recalcul complet des stocks
// stock_publie = stock_initial - SUM(qty lignes de commandes Confirme/Expedie)
// ============================================================

const produits = $('📋 Lire tous les produits').all().map(i => i.json);
const lignes = $('📋 Lire toutes les lignes').all().map(i => i.json);
const commandes = $('📋 Lire commandes actives').all().map(i => i.json);

// Index commandes actives par id
const commandesActives = new Set(commandes.map(c => c.id));

// Compter quantités vendues par produit (commandes Confirme + Expedie)
const ventesByProduit = {};
for (const ligne of lignes) {
  const commandeId = ligne.properties?.commande?.relation?.[0]?.id;
  const produitId = ligne.properties?.produit?.relation?.[0]?.id;
  const qty = ligne.properties?.qty?.number || 0;

  if (!commandesActives.has(commandeId)) continue;
  if (!produitId) continue;

  ventesByProduit[produitId] = (ventesByProduit[produitId] || 0) + qty;
}

// Calculer nouveau stock_publie pour chaque produit
const updates = [];
for (const produit of produits) {
  const stockInitial = produit.properties?.stock_initial?.number || 0;
  const stockActuel = produit.properties?.stock_publie?.number || 0;
  const vendus = ventesByProduit[produit.id] || 0;
  const stockCalcule = Math.max(0, stockInitial - vendus);

  if (stockCalcule !== stockActuel) {
    updates.push({
      notion_id: produit.id,
      nom: produit.properties?.nom?.title?.[0]?.plain_text || '?',
      stock_initial: stockInitial,
      vendus,
      stock_actuel: stockActuel,
      stock_recalcule: stockCalcule,
      diff: stockCalcule - stockActuel
    });
  }
}

console.log(`Réconciliation : ${updates.length} corrections nécessaires sur ${produits.length} produits`);

if (updates.length === 0) return [{ json: { corrections: 0, message: 'Stocks cohérents' } }];
return updates.map(u => ({ json: u }));
